static __forceinline bool pursuit_discard_area(long object_index)
{
    prop_datum *object = BEHAVIOR_DATUM_GET(prop_data, prop_datum, object_index);
    if (object->search_area.value != ZONE_AREA_REF_NONE.value) {
        object->discarded_areas[object->next_discarded_area] = object->search_area;
        object->search_area.zone_index = NONE;
        object->search_area.area_index = NONE;
        object->next_discarded_area = (signed char)((object->next_discarded_area + 1) % 5);
        object->discarded_area_count = (signed char)(object->discarded_area_count + 1 > 5 ? 5 : object->discarded_area_count + 1);
    }
    return true;
}

static __forceinline int game_team_is_enemy(int team_a, int team_b)
{
    int result = true;
    if (team_a == team_b)
        result = false;
    else if (team_a != NONE && (unsigned long)team_a <= 15) {
        long bit = team_a * 16 + team_b;
        result = !(tls_game_allegiance_globals()->enemy_bits[bit >> 5] & (1 << (bit & 31)));
    }
    return result;
}

