static __forceinline void objective_task_request_search(short objective_index, short task_index)
{
    s_task_record *record = objective_get_task_record(objective_index, task_index);
    if (!record->flags.test(_task_record_search_allowed) && !record->flags.test(_task_record_search_requested))
        record->flags.set(_task_record_search_requested, true);
}
static __forceinline short objective_task_search_allowed(short objective_index, short task_index)
{
    s_task_record *record = objective_get_task_record(objective_index, task_index);
    short result = 1;
    if (record->leader != NONE && !record->flags.test(_task_record_search_allowed))
        result = 0;
    else if (record->last_search_time != NONE && game_time_globals->time - record->last_search_time < game_seconds_to_ticks_round(1.0f))
        result = 2;
    return result;
}


