static __forceinline void natural_vector_from_points3d(const real_point3d *a, const real_point3d *b, real_vector3d *result)
{
    result->i = b->x-a->x;
    result->j = b->y-a->y;
    result->k = b->z-a->z;
}
static __forceinline float natural_magnitude_squared3d(const real_vector3d *vector)
{
    return vector->i*vector->i + vector->j*vector->j + vector->k*vector->k;
}
static __forceinline float natural_distance_squared3d(const real_point3d *a, const real_point3d *b)
{
    real_vector3d vector;
    natural_vector_from_points3d(a, b, &vector);
    return natural_magnitude_squared3d(&vector);
}
static __forceinline float natural_game_ticks_to_seconds(float ticks)
{
    return ticks * game_time_globals->tick_length;
}


static __forceinline real_point2d *natural_point_from_line2d(const real_point2d *point, const real_vector2d *direction, float distance, real_point2d *result)
{
    result->x = point->x + direction->i * distance;
    result->y = point->y + direction->j * distance;
    return result;
}
