short actor_executing_layer(long datum_index, short value)
{
  actor_datum *datum = BEHAVIOR_DATUM_GET(actor_data, actor_datum, datum_index);
  short result = -1;
  for (short i = 0; i <= datum->layer_count; i++) {
    if (datum_get_value(datum, i) == value) {
      result = i;
      break;
    }
  }
  return result;
}

long behavior_build_condition_flags(long actor_index)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    short vehicle_state = 0;
    unsigned short flags = 0;
    if (actor->passenger)
        vehicle_state = 2;
    else if (actor->driver)
        vehicle_state = 1;
    if (actor->searching) flags |= 1;
    if (actor->suppress_combat) flags |= 2;
    if (actor->berserking) flags |= 4;
    if (actor->broken) flags |= 8;
    if (actor->cover_flags & 1) flags |= 16;
    long result = (1 << actor->combat_status) | ((1 << vehicle_state) << 10) |
                  ((~flags & 31) << 20) | ((flags & 31) << 25);
    return result;
}
