// @address 0x897e20 g_behavior_posture_variant_counts
// @address 0x519258 behavior_posture_find
extern "C" posture_entry *behavior_posture_find(long character_index, short type, short variant)
{
    posture_entry *result = NULL;
    long type_name = k_behavior_posture_type_names[type];
    long variant_name = NONE;
    if (variant >= 0 && variant < g_behavior_posture_variant_counts[type])
        variant_name = k_behavior_posture_info[k_posture_variant_indices[type][variant]].name;
    while (character_index != NONE) {
        character_definition *definition =
            (character_definition *)tag_get('char', character_index);
        for (short posture = 0; posture < definition->postures.count; posture++) {
            posture_entry *entry = TAG_BLOCK_GET_ELEMENT(&definition->postures, posture, posture_entry);
            if (entry->name == type_name || entry->name == variant_name) {
                result = entry;
                break;
            }
        }
        if (result)
            break;
        character_index = definition->parent_character.index;
    }
    return result;
}

