// @address 0xcac88 ?behavior_self_preservation_decide@@YAFJFPAVc_behavior_state@@@Z
short behavior_self_preservation_decide(long actor_index, short layer, c_behavior_state *parent_state)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    short result;
    if (actor->berserking) {
        result = NONE;
    } else {
        self_preservation_state_data *state = (self_preservation_state_data *)actor_behavior_state_get(actor, layer);
        memcpy(&parent_state->impulse, &state->impulse,
            sizeof(c_behavior_state) - offsetof(c_behavior_state, impulse));
        result = behavior_decide_prioritized(actor_index, layer, parent_state);
        if (result == NONE) {
            state->fallback = true;
            result = 2;
        }
    }
    return result;
}

// @address 0x52ab28 ?actor_behavior_state_allocate@@YAPAVc_behavior_state@@PAUactor_datum@@F@Z
c_behavior_state *actor_behavior_state_allocate(actor_datum *actor, short layer)
{
    if (layer == 0) {
        actor->state_offsets[layer] = 0;
    } else if (layer < 8) {
        short behavior_index = actor_behavior_index_get(actor, (short)(layer-1));
        long state_size = global_behavior_info[behavior_index].state_size;
        short offset = (short)(actor_behavior_state_offset_get(actor, (short)(layer-1)) + state_size);
        actor->state_offsets[layer] = offset;
    }
    return actor_behavior_state_get(actor, layer);
}

