{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    guard_state_data *guard = (guard_state_data *)state;
    if (actor->combat_status > 1 && actor->target_prop_index != NONE
        && BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index)->status >= 1
        && BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index)->status <= 2
        && BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index)->type == 1) {
        actor->look_mode = 4;
        actor->look_direction.to_target();
        actor->lower_weapon_blocked_b = true;
    } else {
        switch (guard->guard_state) {
        case 0:
            if (actor->target_prop_index != NONE) {
                actor->look_mode = 3;
                actor->look_direction.to_target();
                break;
            }
        case 1: case 2: {
            real_vector3d direction;
            if (actor->squad_index != NONE && actor->search_active
                && ::squad_valid_task(BEHAVIOR_DATUM_GET(squad_data, squad_datum, actor->squad_index))
                && objective_task_get_direction(BEHAVIOR_DATUM_GET(squad_data, squad_datum, actor->squad_index)->objective,
                    BEHAVIOR_DATUM_GET(squad_data, squad_datum, actor->squad_index)->task, &direction)) {
                real_vector3d look_vector = direction;
                actor->look_mode = 3;
                actor->look_direction.to_vector(&look_vector);
            } else {
                actor->look_mode = 3;
                actor->look_direction.to_target();
            }
            break;
        }
        }
        actor->pose_allowed = true;
        actor->direction_dirty = true;
        actor->throttle_override_valid = true;
    }
    if (actor_path_finished(actor_index))
        actor->crouch = guard->lower_weapon;
    if (guard->guard_state == 1 && actor->squad_index != NONE) {
        s_task *task = ::squad_get_task(BEHAVIOR_DATUM_GET(squad_data, squad_datum, actor->squad_index));
        if (task && task_get_movement(actor->team, task) == 3)
            actor->moving_crouch = true;
    }
}


