void patrol_choose_random_point(short point_count, c_patrol_state_data *state, bool retry)
{
    c_patrol_state_data *data = state;
    short available_count = 0;
    for (short index = 0; index < point_count; index++) {
        if (!(data->visited_points & (1 << index)))
            available_count++;
    }
    if (available_count > 0) {
        short choice = random_range(get_random_seed_address(), 0, available_count);
        short available_index = 0;
        for (short index = 0; index < point_count; index++) {
            if (!(data->visited_points & (1 << index))) {
                if (available_index == choice) {
                    data->point = index;
                    data->visited_points |= 1 << data->point;
                    break;
                } else
                    available_index++;
            }
        }
    } else {
        data->visited_points = 0;
        data->visited_points |= 1 << data->point;
        patrol_choose_random_point(point_count, state, true);
    }
}
