short vehicle_turtle_get_impulse(long actor_index, c_behavior_state *state)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    object_datum *vehicle = (object_datum *)object_get_and_verify_type(actor->root_vehicle_index, 2);
    character_vehicle_properties *properties = character_vehicle_properties_get(actor_index, vehicle->definition_index);
    bool turtle = (actor->flags & 4) != 0;
    if (properties && actor->target_prop_index != NONE) {
        if ((actor->flags & 4) != 0) {
            if (natural_game_ticks_to_seconds((float)(game_time_globals->time-actor->turtle_time)) < properties->turtle_minimum_time) {
                turtle = true;
            } else if (natural_game_ticks_to_seconds((float)(game_time_globals->time-actor->turtle_time)) > properties->turtle_maximum_time) {
                turtle = false;
            } else {
                character_weapon_properties *weapon = actor_weapon_properties_get(actor_index);
                if (weapon) {
                    prop_ref_datum *ref = BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index);
                    if (ref->distance > weapon->maximum_firing_range)
                        turtle = false;
                }
            }
        } else if (vehicle->body_damage > properties->turtle_speed) {
            turtle = true;
            actor->turtle_time = game_time_globals->time;
        }
    } else {
        turtle = false;
    }
    actor->moving_crouch = turtle;
    actor->crouch = turtle;
    return NONE;
}

