bool emerge_wait_for_actor(long actor_index, long other_actor_index, float *out_distance, short *out_time)
{
    bool wait = false;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    actor_datum *other = BEHAVIOR_DATUM_GET(actor_data, actor_datum, other_actor_index);
    short time = 32767;
    float distance = sqrtf(natural_distance_squared3d(&actor->position.body, &other->position.body));
    if (distance < 4.0f) {
        time = behavior_self_preserve_time_left(other_actor_index);
        if (natural_game_ticks_to_seconds((float)time) < 4.0f)
            wait = true;
    }
    if (out_distance)
        *out_distance = distance;
    if (out_time)
        *out_time = time;
    return wait;
}

