long behavior_emerge_activate(long actor_index, c_behavior_state *state)
{
    bool joined = false;
    long result = NONE;
    joint_invitation_iterator iterator;
    invitation_data *invitation;
    joint_invitation_iterator_new(actor_index, 79, &iterator);
    invitation = joint_invitation_iterator_next(&iterator);
    while (invitation != 0) {
        if (result == NONE) {
            result = joint_accept(actor_index, invitation, (c_joint_behavior_data *)state);
        } else if (invitation->mode == 1) {
            joint_decline(invitation);
        }
        invitation = joint_invitation_iterator_next(&iterator);
    }
    if (result == NONE)
        result = joint_new(actor_index, 79, (c_joint_behavior_data *)state);
    if (result != NONE)
        joined = true;
    if (!joined && result != NONE) {
        joint_withdraw(actor_index, (c_joint_behavior_data *)state);
        result = NONE;
    }
    return result;
}




// @address 0x542d88 ?behavior_emerge_next@@YAFJPAVc_behavior_state@@0@Z
short behavior_emerge_next(long actor_index, c_behavior_state *state, c_behavior_state *next_state)
{
    emerge_state_data *data = (emerge_state_data *)state;
    short result = -2;
    joint_state_datum *joint = BEHAVIOR_DATUM_GET(joint_state_data(), joint_state_datum, data->joint_index);
    short waiting = 0;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    if (actor->target_prop_index != NONE) {
        prop_ref_datum *prop_ref = (prop_ref_datum *)BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index);
        if (prop_ref->awareness >= 1 || prop_ref->stimulus_type >= 2) {
            result = NONE;
        } else if (data->timer > 0) {
            data->timer--;
            if (data->timer <= 0)
                result = NONE;
        } else {
            short emerged = 0;
            for (short i = 0; i < 10; i++) {
                joint_member *participant = &joint->members[i];
                if (participant->actor_index != NONE) {
                    if ((short)participant->status == 0) {
                        if (emerge_wait_for_actor(actor_index, participant->actor_index, 0, 0))
                            waiting++;
                        else
                            joint_reject(data->joint_index, i);
                    } else if ((short)participant->status == 3) {
                        emerged++;
                    }
                }
            }
            if (waiting == 0) {
                result = -2;
                data->timer = (short)game_seconds_to_ticks_round(1.5f);
                if (emerged > 1)
                    actor_dialogue_event(actor_index, 77, NONE, dialogue_state_4, NULL);
            } else {
                waiting = waiting + joint->member_count;
                if (waiting < 2)
                    result = NONE;
            }
        }
    } else {
        result = NONE;
    }
    return result;
}

void behavior_emerge_control(long actor_index, c_behavior_state *state, joint_state_datum *joint_state)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    prop_ref_datum *prop_ref = BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index);
    prop_view *view = prop_view_get(prop_ref);
    if (view && view->sighting_search_state <= 0 && !(view->flags & 0x40)) {
        actor->look_mode = 4;
        actor->look_direction.to_target();
    } else {
        long unit_index = NONE;
        for (short i = 0; i < 10; i++) {
            joint_member *member = &joint_state->members[i];
            if (member->actor_index != NONE && member->actor_index != actor_index)
                unit_index = BEHAVIOR_DATUM_GET(actor_data, actor_datum, member->actor_index)->unit_index;
        }
        if (unit_index != NONE) {
            actor->aim_mode = 2;
            actor->aim_direction.to_object(unit_index);
        }
    }
    actor->direction_dirty = true;
}

