// @address 0x543b20 ?behavior_coverfriend_control@@YAXJPAVc_behavior_state@@@Z
void behavior_coverfriend_control(long actor_index, c_behavior_state *state)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    prop_ref_datum *ref = BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index);
    prop_state *target = prop_state_from_view_or_prop(ref);
    prop_view *view = (prop_view *)prop_view_get(ref);
    long weapon_index = actor_get_weapon(actor_index);
    if (ref->status >= 1 && ref->status <= 2) {
        actor->lower_weapon_blocked_b = true;
        actor->look_mode = 4;
        actor->look_direction.to_target();
    } else if (view) {
        c_ai_point3d point = view->pathfinding_point;
        point.position.z += target->height-target->base_position.z;
        real_point3d position;
        ai_point_get_position(&point, &position);
        actor->look_mode = 4;
        actor->look_direction.to_point(&position);
        actor->aim_mode = 2;
        actor->aim_direction.to_point(&position);
        actor->lower_weapon_blocked_b = true;
        actor->allow_unseen_target_fire = true;
        actor->move_target_type = 2;
        actor->move_target_point = point;
        if (weapon_index != NONE) {
            object_datum *weapon = (object_datum *)object_get_and_verify_type(weapon_index, 4);
            character_weapon_properties *properties = character_weapon_properties_get(
                BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index)->character_index, weapon->definition_index);
            if (properties) {
                short difficulty = game_globals->options.game_mode == 1 ? game_globals->options.campaign_difficulty : 1;
                float *burst;
                switch (difficulty) {
                case 2: burst = properties->burst[1]; break;
                case 3: burst = properties->burst[2]; break;
                default: burst = properties->burst[0]; break;
                }
                actor->burst_length = burst[1];
            }
        }
    }
}

