short behavior_activity_next(long actor_index, c_behavior_state *state, c_behavior_state *next_state)
{
    activity_state *activity_state_state = (activity_state *)state;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    short result = -2;
    bool finished = false;
    if ((unsigned short)actor->activity_index == 0xffff)
        finished = true;
    else if (!behavior_activity_can_execute(actor_index))
        finished = true;
    else if (behavior_activity_command_allows(actor_index)) {
        const s_activity_info *activity = &g_activity_info[actor->activity_index];
        short exit_status = g_activity_exit_combat_status[activity->data[0]];
        short interruption_status = exit_status;
        if (actor->squad_index != NONE) {
            squad_datum *squad = BEHAVIOR_DATUM_GET(squad_data, squad_datum, actor->squad_index);
            if (::squad_valid_task(squad)) {
                s_task *task = (s_task *)objective_get_task((short)squad->objective, (short)squad->task);
                long movement = task_get_movement(actor->team, task);
                short forced_status = k_movement_combat_status_table[k_movement_combat_status_index[movement]];
                if (exit_status <= forced_status)
                    interruption_status = (short)(forced_status + 1);
            }
        }
        if (actor->combat_status >= exit_status && (actor->target_prop_index != NONE || actor->danger_zone.danger_type > 0))
            finished = true;
        else if (exit_status < 10) {
            if (activity_state_state->interruption_ticks > 0) {
                activity_state_state->interruption_ticks--;
                if (activity_state_state->interruption_ticks == 0)
                    finished = true;
            } else if (actor->combat_status >= interruption_status)
                activity_state_state->interruption_ticks =
                    (short)game_seconds_to_ticks_round((float)random_range(get_random_seed_address(), 2, 6));
        }
        if (!finished) {
            switch (activity->data[0]) {
            case 0:
                finished = false;
                break;
            case 3: {
                prop_ref_chain_iterator iterator;
                prop_ref_chain_iterator_new(&iterator, actor_index);
                prop_ref_datum *reference;
                while ((reference = prop_ref_chain_iterator_next(&iterator)) != 0) {
                    if (reference->stimulus == 2 && BEHAVIOR_DATUM_GET(prop_data, prop_datum, reference->prop_index)->hostile) {
                        finished = true;
                        break;
                    }
                }
                break;
            }
            }
            if (!finished && (activity->data[0] == 0 || activity->data[0] == 3) && !motor_animation_busy(actor->unit_index)) {
                s_game_globals *globals = global_game_globals;
                bool flee = false;
                if (globals && globals->ai_globals.count() > 0) {
                    const s_ai_globals_definition *properties = (const s_ai_globals_definition *)globals->ai_globals.address;
                    if (actor->activity_scariness >= properties->danger_shooting_at - 0.1f)
                        flee = true;
                }
                if (!flee && actor->danger_zone.danger_type > 0) {
                    bool vehicle = false;
                    bool imminent = false;
                    if (actor_assess_danger(actor_index, 0.0f, 0, &vehicle, 0, &imminent, 0) && vehicle && imminent)
                        flee = true;
                }
                if (flee)
                    ::actor_impulse_submit(actor_index, 778, 0, 0);
            }
        }
    }
    if (finished) {
        behavior_activity_reset(actor_index);
        result = -1;
    }
    return result;
}


