// Sets or clears the vehicle's ready bit, keeping the joint's ready count in step.
void actor_ready_to_flip(long actor_index, bool ready, c_vehicle_flip_data *vehicle_flip_data, joint_vehicle_flip_data *joint_flip_data)
{
    if (ready)
    {
        if (!(vehicle_flip_data->flags & 1))
        {
            joint_flip_data->ready_count++;
            vehicle_flip_data->flags |= 1;
        }
    }
    else if (vehicle_flip_data->flags & 1)
    {
        joint_flip_data->ready_count--;
        vehicle_flip_data->flags &= ~1;
    }
}


// @address 0x5366b8 ?behavior_formation_select_actors@@YAFJJPAVc_behavior_state@@@Z
short behavior_formation_select_actors(long actor_index, long joint_index, c_behavior_state *state)
{
    short count = 0;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    formation_state *formation = (formation_state *)state;
    if (formation->target != NONE) {
        ai_index_actor_iterator iterator;
        ai_index_actor_iterator_new(formation->target, &iterator);
        actor_datum *other;
        while ((other = ai_index_actor_iterator_next(&iterator)) != 0) {
            if (other != actor && actor->type == other->type) {
                if (invite_actor(actor_index, iterator.actor_index, joint_index, 3, 1.0f))
                    count++;
            }
        }
    } else if (actor->squad_index != NONE) {
        squad_actor_iterator iterator;
        squad_actor_iterator_new(&iterator, actor->squad_index, true);
        actor_datum *other;
        while ((other = ::squad_actor_iterator_next(&iterator)) != 0) {
            if (other != actor && actor->type == other->type) {
                if (invite_actor(actor_index, iterator.index, joint_index, 3, 1.0f))
                    count++;
            }
        }
    }
    return count;
}

