// @address 0xb6c10 ?test_child_entry@@YAXJPAUchild_entry@@PAF1PAVc_behavior_state@@2@Z
void test_child_entry(long actor_index, child_entry *entry, short *behavior_index, short *desire, c_behavior_state *state, c_behavior_state *child_state)
{
    short index = entry->behavior_index;
    *behavior_index = NONE;
    *desire = 0;
    if (index >= 0 && index < 197) {
        Behavior_header *header = global_behavior_info[index].header;
        if (header->kind != g_action_selection_nonce && (header->flags & global_condition_flags) == global_condition_flags &&
            bit_vector_test(global_style_vector, index))
        {
            actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
            bool test = false;
            switch (entry->test_type) {
            case 0:
                test = true;
                break;
            case 1:
                test = entry->test_index >= 0 && entry->test_index < 14
                    && (actor->child_test_times[entry->test_index] == NONE
                        || natural_game_ticks_to_seconds((float)(game_time_globals->time - actor->child_test_times[entry->test_index])) > entry->test_seconds);
                break;
            case 2:
                test = game_time_globals->time - state->start_time == 0;
                break;
            case 3:
                test = (actor->stimulus_flags & (1 << entry->test_index)) != 0;
                break;
            }
            if (test) {
                if (header->type == 0) {
                    Behavior_impulse *impulse = static_cast<Behavior_impulse *>(header);
                    short decided = impulse->get_impulse(actor_index, child_state);
                    if (decided >= 0 && decided < 197) {
                        Behavior_header *decided_header = global_behavior_info[decided].header;
                        if (decided_header->kind != g_action_selection_nonce &&
                            (decided_header->flags & global_condition_flags) == global_condition_flags &&
                            bit_vector_test(global_style_vector, decided))
                        {
                            *behavior_index = decided;
                            *desire = 3;
                        }
                    }
                } else {
                    Behavior *child = static_cast<Behavior *>(header);
                    short (*get_desire)(long, const s_behavior_input *, const s_behavior_arguments *) = child->get_desire;
                    *behavior_index = index;
                    if (get_desire) {
                        const s_behavior_input *input = (const s_behavior_input *)&child_state->impulse.type;
                        const s_behavior_arguments *arguments = entry->has_arguments ? &entry->arguments : 0;
                        *desire = get_desire(actor_index, input, arguments);
                    } else
                        *desire = 0;
                }
                if (entry->test_index >= 0 && entry->test_index < 14)
                    actor->child_test_times[entry->test_index] = game_time_globals->time;
            }
        }
    }
}
