const float k_behavior_pickup_real_max = 3.402823466e+38f;
// @address 0x53fc58 ?pickup_find_passenger@@YAJJ@Z
long pickup_find_passenger(long actor_index)
{
    long result = NONE;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    if ((short)actor->pickup_player != NONE && actor->pickup_wait_ticks > game_time_seconds_to_ticks_round(2.0f)) {
        ai_player_state *state = &tls_ai_players()[(short)actor->pickup_player];
        if (state->id != NONE) {
            player_datum *player = BEHAVIOR_DATUM_GET(player_data, player_datum, state->id);
            if (game_globals->options.game_mode != 1 || !(unsigned char)game_team_is_enemy((e_game_team)actor->team,
                (e_game_team)player->configuration.host.team_index))
                return player->unit_index;
        }
    }
    float best_distance_squared = k_behavior_pickup_real_max;
    unit_seat_source seats[64];
    short seat_count = pickup_unit_get_all_seats(actor->root_vehicle_index, seats, 64);
    for (short seat = 0; seat < seat_count; seat++) {
        if (seats[seat].definition->test_flag(11))
            continue;
        short unit_seat_index = seats[seat].seat_index;
        long unit_index = seats[seat].unit_index;
        long passenger_index = ::ai_vehicle_get_reservation(unit_index, unit_seat_index, (e_game_team)actor->team);
        if (passenger_index != NONE && ::unit_seat_get_occupant(unit_index, unit_seat_index) == NONE) {
            actor_datum *passenger = BEHAVIOR_DATUM_GET(actor_data, actor_datum, passenger_index);
            if ((short)passenger->vehicle_desire >= 3) {
                float distance_squared = natural_distance_squared3d(&passenger->position.body, &actor->position.body);
                if (distance_squared < best_distance_squared) {
                    best_distance_squared = distance_squared;
                    result = passenger->unit_index;
                }
            }
        }
    }
    return result;
}



