static __forceinline void behavior2_ai_scratch_free(void *memory)
{
    long remaining = 0;
    for (long i = 0; i < 2; i++) {
        if (g_ai_scratch_buffers[i].in_use && g_ai_scratch_buffers[i].address == memory)
            g_ai_scratch_buffers[i].in_use = false;
        if (g_ai_scratch_buffers[i].in_use)
            ++remaining;
    }
    if (remaining == 0) {
        g_ai_scratch_flags[1] = false;
        if (g_ai_scratch_flags[0])
            ::havok_memory_update_initialize();
    }
}
