static __forceinline long behavior2_seconds_to_ticks_round(float seconds)
{
    float ticks = (float)game_time_globals->ticks_per_second * seconds;
    return (long)(ticks + 0.5f);
}
// @address 0x530ae8 ?behavior_cover_activate@@YA_NJPAVc_behavior_state@@@Z
bool behavior_cover_activate(long actor_index, c_behavior_state *state)
{
    character_cover_properties *properties = character_definition_cover_multi_properties_get(actor_index);
    c_cover_state_data *cover = (c_cover_state_data *)state;
    if (!(cover->flags & 1)) {
        float time = real_random_range(get_random_seed_address(), properties->cover_time_lower, properties->cover_time_upper);
        cover->flags |= 2;
        cover->flags &= ~8;
        cover->flags &= ~4;
        cover->flags |= 1;
        cover->flags &= ~128;
        cover->flags &= ~16;
        cover->cover_timer = 0;
        cover->desired_ticks = (short)behavior2_seconds_to_ticks_round(time);
        behavior_actor_path_clear(actor_index);
        if (time < 0.0f)
            cover->flags |= 32;
        else {
            cover->timer = cover->desired_ticks;
            cover->flags &= ~32;
        }
    }
    cover->flags &= ~64;
    cover->state = 0;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    actor->cover_index = NONE;
    actor->cover_flags &= ~3;
    actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    if (actor->target_prop_index != NONE && actor->target_age > behavior2_seconds_to_ticks_round(0.5f))
        cover->flags |= 256;
    return true;
}


static __forceinline real_vector2d *behavior2_vector_from_points2d(const real_point2d *a, const real_point2d *b, real_vector2d *vector)
{
    vector->i = b->x - a->x;
    vector->j = b->y - a->y;
    return vector;
}
static __forceinline float behavior2_dot_product2d(const real_vector2d *a, const real_vector2d *b)
{
    return a->i * b->i + a->j * b->j;
}
// @address 0x545480 ?behavior_grapple_control@@YAXJPAVc_behavior_state@@@Z
void behavior_grapple_control(long actor_index, c_behavior_state *state)
{
    behavior2_grapple_state *grapple = (behavior2_grapple_state *)state;
    if (grapple->force_field) {
        actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
        actor->control_flags |= 8192;
    } else if (actor_path_executing(actor_index)) {
        actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
        prop_ref_datum *target = BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index);
        prop_state *target_state = prop_state_get(target);
        real_vector2d direction;
        behavior2_vector_from_points2d(&actor->position.body.xy, &target_state->base_position.xy, &direction);
        if (normalize2d(&direction) > 0.0f) {
            real_vector2d facing = actor->facing_vector.xy;
            if (normalize2d(&facing) > 0.0f && behavior2_dot_product2d(&facing, &direction) > 0.9f)
                actor->boost_allowed = true;
        }
    }
}


static __forceinline bool behavior2_clump_kamikaze_allowed(long actor_index, long clump_index)
{
    short kamikaze_count = 0;
    clump_datum *clump = BEHAVIOR_DATUM_GET(clump_data, clump_datum, clump_index);
    s_character_charge_entry *entry = character_definition_charge_entry_get(actor_index);
    short max_kamikazes;
    if (entry)
        max_kamikazes = entry->max_kamikazes;
    else
        max_kamikazes = 32767;
    if (clump->active) {
        clump_actor_iterator iterator;
        clump_actor_iterator_new(&iterator, clump);
        while (clump_actor_iterator_next(&iterator)) {
            if (actor_executing_layer(iterator.actor_index, 18) != NONE)
                kamikaze_count++;
        }
    }
    return kamikaze_count < max_kamikazes;
}
