static __forceinline void behavior_style_and_range(s_style_flags *result, const s_style_flags *left, const s_style_flags *right, long count)
{
    const unsigned long *a = left->bits;
    const unsigned long *b = right->bits;
    long i = 0;
    do {
        result->bits[i] = a[i] & b[i];
        i++;
    } while (i < (count + 31) >> 5);
}

