unsigned long global_style_vector[7];
static __forceinline s_style_flags *behavior2_global_style_vector()
{
    return (s_style_flags *)global_style_vector;
}
// @address 0x52a8a0 ?generate_style_vector@@YAXJ@Z
void generate_style_vector(long actor_index)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    bool style_overridden = false;
    bool vehicle_style = false;
    if (actor->command_index != NONE) {
        command_script_datum *command = BEHAVIOR_DATUM_GET(command_script_data, command_script_datum, actor->command_index);
        if (command->style_index_valid) {
            behavior2_style_definition *style =
                (behavior2_style_definition *)tag_get('styl', command->style_index);
            *behavior2_global_style_vector() = style->flags;
            style_overridden = true;
        }
    }
    if (!style_overridden) {
        if (actor->squad_index != NONE) {
            squad_datum *squad = BEHAVIOR_DATUM_GET(squad_data, squad_datum, actor->squad_index);
            *behavior2_global_style_vector() = squad->style;
        } else {
            *behavior2_global_style_vector() = style_all;
        }
    }
    if (actor->root_vehicle_index != NONE && !actor->vehicle_style_disabled) {
        object_datum *vehicle = (object_datum *)object_get_and_verify_type(actor->root_vehicle_index, 8195);
        character_vehicle_properties *properties = character_vehicle_properties_get(actor_index, vehicle->definition_index);
        if (properties && properties->style.index != NONE) {
            behavior2_style_definition *style = (behavior2_style_definition *)tag_get('styl', properties->style.index);
            behavior_style_and_range(behavior2_global_style_vector(), behavior2_global_style_vector(), &style->flags, 197);
            vehicle_style = true;
        }
    }
    if (!vehicle_style) {
        character_definition *character =
            (character_definition *)tag_get('char', actor->character_index);
        if (character->style.index != NONE) {
            behavior2_style_definition *style =
                (behavior2_style_definition *)tag_get('styl', character->style.index);
            behavior_style_and_range(behavior2_global_style_vector(), behavior2_global_style_vector(), &style->flags, 197);
        }
    }
    if (!ai_globals->perception_enabled) {
        for (short index = 0; index < 197; ++index) {
            if (global_behavior_info[index].inhibit_flags & 8)
                behavior2_global_style_vector()->bits[index >> 5] &= ~(1UL << (index & 31));
        }
    }
}


