static __forceinline float behavior2_formation_normalize2d(real_vector2d *vector)
{
    float length = sqrtf(vector->i * vector->i + vector->j * vector->j);
    if (fabsf(length) >= 0.0001f) {
        float inverse = 1.0f / length;
        vector->i = vector->i * inverse;
        vector->j = vector->j * inverse;
        return length;
    }
    return 0.0f;
}
