static __forceinline bool behavior_vehicle_fight_target_in_vehicle(long actor_index)
{
    bool in_vehicle = false;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    prop_ref_datum *ref = BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, actor->target_prop_index);
    if (actor->target_prop_index != NONE && ref->view_index != NONE)
    {
        tracking_datum *prop = BEHAVIOR_DATUM_GET(TLS_PROP_DATA, tracking_datum, ref->view_index);
        if (prop->state.vehicle_index == actor->root_vehicle_index)
            in_vehicle = true;
    }
    return in_vehicle;
}
