bool behavior_perimeter_perform(long actor_index, c_behavior_state *state)
{
    flank_state_data *data = (flank_state_data *)state;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    bool result = true;
    do {
        if (fp_ref_equals(actor->firing_position_reference, FP_REF_NONE))
            data->started = true;
        else if (actor_path_finished(actor_index))
        {
            if (target_get_prop_class(actor) <= 4)
            {
                result = false;
                break;
            }
            if (!data->started && data->timer > game_time_seconds_to_ticks_round(1.0f))
            {
                data->started = true;
                actor_discard_firing_position(actor_index, actor->firing_position_reference, false);
            }
        }
        if (actor->uncovering && data->started)
        {
            firing_position_evaluation_context context;
            memset(&context, 0, sizeof(context));
            context.type = 0;
            context.preferred_flags = 6;
            context.attack_range_minimum = 3.0f;
            context.attack_range_maximum = 6.0f;
            context.attack_range_distance = 8.0f;
            context.attractor_valid = true;
            context.attractor_weight = 25.0f;
            context.attractor_radius = 2.0f;
            real_vector3d battle_vector;
            if (prop_get_battle_vector(actor->target_prop_index, &battle_vector, NULL))
            {
                context.hint = true;
                context.negative = true;
                context.target_hint_vector = battle_vector;
            }
            if (!fp_ref_equals(actor->firing_position_reference, FP_REF_NONE))
            {
                context.former_enabled = true;
                context.former_position_index = actor->firing_position_reference;
                context.former_strongly = true;
            }
            c_path_state path;
            bool found;
            long previous_owner;
            firing_position position;
            firing_position_ref selected = actor_active_select_firing_position(
                actor_index, &context, &position, &previous_owner, (path_state *)path.m_data, &found);
            if (!fp_ref_equals(selected, FP_REF_NONE))
            {
                actor_change_firing_position(actor_index, selected, &position, previous_owner, found ? (path_state *)path.m_data : NULL, true);
                if (fp_ref_equals(actor->firing_position_reference, FP_REF_NONE))
                    actor_discard_firing_position(actor_index, selected, false);
                data->started = false;
            }
        }
    } while (false);
    return result;
}
