static __forceinline float behavior_fast_vector_intersection_with_sphere(
    const real_point3d *origin, const real_vector3d *direction, const real_point3d *center, float radius)
{
    float dx = origin->x - center->x;
    float dy = origin->y - center->y;
    float dz = origin->z - center->z;
    float c = dx*dx + dy*dy + dz*dz - radius*radius;
    if (c < 0.0f)
        return 0.0f;
    float b = dx*direction->i + dy*direction->j + dz*direction->k;
    if (b >= 0.0f)
        return 3.4028234663852886e+38f;
    float a = direction->i*direction->i + direction->j*direction->j + direction->k*direction->k;
    float disc = b*b - a*c;
    if (disc <= 0.0f)
        return 3.4028234663852886e+38f;
    return (-b - sqrtf(disc)) / a;
}
