    {
        real_point3d point;
        ai_point_get_position(&cower->point, &point);
        actor->look_mode = 4;
        actor->look_direction.to_point(&point);
    }
    if (behavior_flee_get_desire(actor_index, 0, 0) >= 3)
    {
        Behavior_header *header = global_behavior_info[84].header;
        if (header->kind != g_action_selection_nonce && (header->flags & global_condition_flags) == global_condition_flags &&
            bit_vector_test(global_style_vector, 84))
            result = 84;
        else if (cower->forced_ticks == 0)
            result = behavior_decide_prioritized(actor_index, layer, parent_state);
    }
    else if (cower->forced_ticks == 0)
        result = behavior_decide_prioritized(actor_index, layer, parent_state);
