        long index;
        bool found;
        firing_position_evaluation_context context;
        memset(&context, 0, sizeof(context));
        context.type = 0;
        context.preferred_flags = 1;
        context.prefer_flags = true;
        context.use_current_position = true;
        context.ignore_dynamic_firing_positions = true;
