                collision_result main_collision;
                c_sector_ref start_sector = pathfinding_find_ground_sector(point, global_up3d, 0, &main_collision, 0.5f);

                forward.i = direction_i;
                forward.j = direction_j;
                forward.k = 0.0f;
                short projection = 2;
                bool projection_sign = true;
                if (speed <= 0.2f)
                    speed = 0.2f;

