// @address 0x540010 ?behavior_vehicle_pickup_perform@@YA_NJPAVc_behavior_state@@@Z
bool behavior_vehicle_pickup_perform(long actor_index, c_behavior_state *state)
{
    bool result = true;
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    vehicle_pickup_state_data *data = (vehicle_pickup_state_data *)state;
    real_point3d origin;
    object_get_origin(data->unit_index, &origin);
    float y_distance = actor->position.body.y - origin.y;
    float z_distance = actor->position.body.z - origin.z;
    float x_distance = actor->position.body.x - origin.x;
    float distance_squared = x_distance * x_distance + (z_distance * z_distance + y_distance * y_distance);
    if (distance_squared < 16.0f && !data->announced && data->repositioned)
    {
        unit_datum *unit = (unit_datum *)object_get_and_verify_type(data->unit_index, 3);
        if (unit->unit.player_index != NONE)
        {
            bool seat_free = false;
            unit_seat_source seats[64];
            short seat_count = 0;
            unit_get_all_seats_internal(actor->root_vehicle_index, (unit_seat_source *)seats, &seat_count, 64, false);
            for (short i = 0; i < seat_count; i++)
            {
                if (unit_seat_test_flag(seats[i].unit_index, seats[i].seat_index, _unit_seat_gunner_bit)
                    && unit_seat_get_occupant(seats[i].unit_index, seats[i].seat_index) == NONE)
                {
                    seat_free = true;
                    break;
                }
            }
            bool spoke;
            if (seat_free)
                spoke = actor_dialogue_event(actor_index, 109, data->unit_index, NULL);
            else
                spoke = actor_dialogue_event(actor_index, 107, data->unit_index, NULL);
            if (spoke)
            {
                long prop_ref_index = prop_ref_get_by_object_index(actor_index, data->unit_index, false, _clump_importance_none);
                if (prop_ref_index != 0)
                    BEHAVIOR_DATUM_GET(prop_data, prop_datum, BEHAVIOR_DATUM_GET(prop_ref_data, prop_ref_datum, prop_ref_index)->prop_index)->flags |= 1;
            }
            data->announced = true;
        }
    }
    if (actor->uncovering)
    {
        if (distance_squared < 4.0f)
        {
            behavior_actor_path_clear(actor_index);
        }
        else if (distance_squared > 16.0f)
        {
            firing_position_evaluation_context context;
            memset(&context, 0, sizeof(context));
            context.influences[0].radius = 10.0f;
            context.use_current_position = true;
            context.influences[0].positive = true;
            context.type = 4;
            context.influences[0].position = origin;
            context.influence_count++;
            c_path_state path;
            bool found = false;
            long previous_owner = NONE;
            cover_firing_slot position;
            firing_position_ref selected = actor_select_firing_position(
                actor_index, &context, &position.as_position, &previous_owner, (path_state *)path.m_data, &found);
            if (!fp_ref_equals(selected, FP_REF_NONE))
            {
                float new_y_distance = position.as_position.position.y - origin.y;
                float new_z_distance = position.as_position.position.z - origin.z;
                float new_x_distance = position.as_position.position.x - origin.x;
                float new_distance_squared = new_x_distance * new_x_distance + (new_z_distance * new_z_distance + new_y_distance * new_y_distance);
                if (new_distance_squared < distance_squared && !fp_ref_equals(selected, actor->firing_position_reference))
                {
                    selected = actor_change_firing_position(
                        actor_index, selected, &position.as_position, previous_owner, found ? (path_state *)path.m_data : NULL, true);
                    if (!fp_ref_equals(selected, FP_REF_NONE))
                        data->repositioned = true;
                }
            }
            if (fp_ref_equals(selected, FP_REF_NONE))
            {
                BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index)->uncovering = false;
                if (distance_squared > 100.0f)
                {
                    unit_datum *target_unit = (unit_datum *)object_get_and_verify_type(data->unit_index, 3);
                    if (target_unit->unit.actor_index != NONE)
                    {
                        actor_attach_to_vehicle(target_unit->unit.actor_index, NONE, false);
                        result = false;
                    }
                }
            }
        }
    }
    return result;
}

