    real_point3d position = actor->position.body;
    const real_vector3d *up;
    if (mover_has_variable_camera_up(actor->unit_index))
        up = &((object_datum *)object_get_and_verify_type(actor->unit_index, 12291))->up;
    else
        up = &k_real_math_identity_matrix_storage.up;
