        position.y = position.y - direction.j * 2.0f;
        position.z = position.z - direction.k * 2.0f;
        distance = prop_ref->distance;
        target.location[1] = NONE;
        target.point = position;
        break;
    case 1:
        position.x = actor->position.body.x + direction.i;
        position.y = actor->position.body.y + direction.j;
        position.z = actor->position.body.z + direction.k;
        target.location[1] = NONE;
        target.point = position;
        break;
