extern "C" bool behavior_compute_avoid_vector(long actor_index, float minimum_magnitude, real_vector3d *avoid_vector)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    bool result = false;
    real_vector3d danger_direction = actor->danger_zone.velocity;
    real_vector3d offset;
    real_vector3d direction;
    natural_vector_from_points3d(&actor->danger_zone.position, &actor->position.body, &offset);
    if (normalize3d(&danger_direction) > minimum_magnitude && (unsigned short)actor->vehicle_driver_type != 3)
    {
        character_movement_properties *movement = character_definition_movement_properties_get(actor->character_index);
        float radius = movement ? movement->pathfinding_radius : 0.3f;
        real_vector3d perpendicular;
        perpendicular.i = -danger_direction.j;
        perpendicular.j = danger_direction.i;
        perpendicular.k = danger_direction.k;
        float side = dot_product3d(&offset, &perpendicular);
        if (side > 0.0f)
            direction = perpendicular;
        else
            scale_vector3d(&perpendicular, -1.0f, &direction);

        real_vector3d danger_offset;
        natural_vector_from_points3d(&actor->danger_zone.position, &actor->position.body, &danger_offset);
        float danger_distance = dot_product3d(&danger_offset, &perpendicular);
        if (danger_distance * side < 0.0f)
            danger_distance *= -1.0f;

        direction.k = 0.0f;
        if (normalize3d(&direction) == 0.0f)
            direction = *global_forward3d;

        float distance = MAX(actor->danger_zone.radius - danger_distance, 0.2f) + radius;

        float fraction;
        if (!actor_moving_can_move_along_vector(actor_index, &direction, distance, 0.0f, NULL, &fraction))
        {
            if (actor->danger_zone.state == 0)
            {
                real_vector3d reverse;
                scale_vector3d(&direction, -1.0f, &reverse);
                float reverse_fraction;
                if (!actor_moving_can_move_along_vector(actor_index, &direction, distance, 0.0f, NULL, &reverse_fraction))
                {
                    if (fraction > reverse_fraction)
                        scale_vector3d(&direction, fraction * distance * 0.9f, &direction);
                    else
                        scale_vector3d(&reverse, reverse_fraction * distance * 0.9f, &direction);
                }
                else
                {
                    scale_vector3d(&direction, distance, &direction);
                }
            }
            else
            {
                scale_vector3d(&direction, fraction * distance * 0.9f, &direction);
            }
        }
        else
        {
            scale_vector3d(&direction, distance, &direction);
        }
        if (sqrtf(natural_magnitude_squared3d(&direction)) > radius)
            result = true;
    }
    else
    {
        direction = offset;
        direction.k = 0.0f;
        if (normalize3d(&direction) == 0.0f)
            direction = *global_forward3d;
        result = true;
    }
    *avoid_vector = direction;
    return result;
}

