bool behavior_activity_activate(long actor_index, c_behavior_state *behavior_state)
{
    actor_datum *actor = BEHAVIOR_DATUM_GET(actor_data, actor_datum, actor_index);
    actor->flags &= 0xf7ffffff;
    c_kamikaze_state_data *state = static_cast<c_kamikaze_state_data *>(behavior_state);
    state->clear_tag = -1;
    state->type = actor->activity_index;
    state->variant = actor->activity_variant;
    unsigned long activity = g_activity_info[actor->activity_index].data[1];
    switch (activity) {
    case 0:
        ::actor_stow_weapon(actor_index, true, false);
        break;
    case 1:
        ::actor_stow_weapon(actor_index, false, false);
        break;
    case 2:
        {
            bool stow = actor->combat_status <= 1;
            ::actor_stow_weapon(actor_index, stow, false);
        }
        break;
    }
    if (actor->unit_index != NONE) {
        posture_entry *entry = behavior_posture_find(actor->character_index, actor->activity_index, actor->activity_variant);
        if (entry && entry->attachment.index != NONE) {
            object_placement_data placement;
            object_placement_data_new(&placement, entry->attachment.index, actor->unit_index, 0);
            placement.parent_object_index = actor->unit_index;
            placement.parent_marker = entry->parent_marker;
            placement.child_marker = entry->child_marker;
            object_new(&placement);
        }
    }
    return true;
}

static __forceinline s_tag_block *behavior_equipment_block_get(long character_index)
{
    s_tag_block *result = NULL;
    while (character_index != NONE) {
        character_definition *definition =
            (character_definition *)tag_get('char', character_index);
        if (definition->equipment_properties.count > 0) {
            result = &definition->equipment_properties;
            break;
        }
        character_index = definition->parent_character.index;
    }
    return result;
}

